insert into public.projects (id,ref,title,client_id,type,status,description,start_date,delivery_date,completed_date,total_price,steps)
select id,ref,title,client_id,type,status,description,start_date,delivery_date,completed_date,total_price,steps from jsonb_to_recordset($j$[{"id":"5ffd33ba-0756-4df9-9bd5-d4a4115d932c","ref":"LUX-P001","title":"Custom living room set","client_id":"8363fa40-c6b3-4d31-aed6-0a2dba8cbd18","type":"custom","status":"finished","description":"Curved bouclé sofa, two lounge chairs and a travertine coffee table for a sea-view villa living room.","start_date":"2026-02-26","delivery_date":"2026-04-29","completed_date":"2026-04-25","total_price":68000,"steps":{"design":true,"materials":true,"fabrication":true,"finishing":true,"delivery":true}},{"id":"1c9eb74d-15ce-47e4-9679-780a0595b7ca","ref":"LUX-P002","title":"Riad dining room","client_id":"371d9311-01ac-48d8-9201-9aabd218baa4","type":"custom","status":"finished","description":"Solid walnut dining table for 12 guests with upholstered chairs and a carved sideboard for the riad’s main patio.","start_date":"2026-03-29","delivery_date":"2026-05-29","completed_date":"2026-05-27","total_price":124000,"steps":{"design":true,"materials":true,"fabrication":true,"finishing":true,"delivery":true}},{"id":"9558f339-1b18-4a0f-b5a5-8bcce5a8b180","ref":"LUX-P003","title":"Hotel lobby furniture","client_id":"f28473f4-180f-4212-a8aa-82c6ab39f3b1","type":"interior","status":"finished","description":"Full lobby redesign: modular seating islands, reception desk in fluted oak and brass, lighting and decoration.","start_date":"2026-04-24","delivery_date":"2026-07-23","completed_date":"2026-07-26","total_price":385000,"steps":{"design":true,"materials":true,"fabrication":true,"finishing":true,"delivery":true}},{"id":"23bc7466-ba71-449f-a221-d4b4aca68359","ref":"LUX-P004","title":"Office meeting room","client_id":"2340404a-0417-43ce-a324-119ca600f050","type":"catalog","status":"finished","description":"Meeting table for 10 with ergonomic chairs and a storage wall, selected from the catalog.","start_date":"2026-06-17","delivery_date":"2026-07-16","completed_date":"2026-07-17","total_price":46500,"steps":{"design":true,"materials":true,"fabrication":true,"finishing":true,"delivery":true}},{"id":"9ba868b8-debb-47d5-8c73-07fddff91e18","ref":"LUX-P005","title":"Master bedroom set","client_id":"5b4ff06b-eb2c-41af-96b1-9a413ee55ef5","type":"custom","status":"finished","description":"Upholstered king-size bed with integrated headboard lighting, bedside tables and bench.","start_date":"2026-07-16","delivery_date":"2026-09-14","completed_date":"2026-09-16","total_price":52000,"steps":{"design":true,"materials":true,"fabrication":true,"finishing":true,"delivery":true}},{"id":"97da101f-1150-4b05-a8e2-2948ac2c7e86","ref":"LUX-P006","title":"Fitted kitchen — oak & lacquer","client_id":"b082e785-0ac7-4e38-bdb7-9f5bf70fbb8e","type":"custom","status":"finished","description":"Made-to-measure kitchen with olive matt lacquer columns, oak island and integrated LED niches.","start_date":"2026-08-06","delivery_date":"2026-10-08","completed_date":"2026-10-10","total_price":89000,"steps":{"design":true,"materials":true,"fabrication":true,"finishing":true,"delivery":true}},{"id":"9dd83bbb-7788-4f3a-9d08-a7016332a9da","ref":"LUX-P007","title":"Café terrace furniture","client_id":"300e7684-a435-461d-813c-686b2ed06563","type":"catalog","status":"finished","description":"Outdoor tables, stackable chairs and parasols for the café’s new terrace.","start_date":"2026-09-29","delivery_date":"2026-11-02","completed_date":"2026-11-03","total_price":31800,"steps":{"design":true,"materials":true,"fabrication":true,"finishing":true,"delivery":true}},{"id":"46b32ae4-9827-45d6-b592-a26820ac691c","ref":"LUX-P008","title":"Hotel suites — 12 rooms","client_id":"f28473f4-180f-4212-a8aa-82c6ab39f3b1","type":"interior","status":"in_progress","description":"Interior design and furniture for 12 sea-view suites: beds, dressing, desks, lounge corners and textiles.","start_date":"2026-08-25","delivery_date":"2026-12-30","completed_date":null,"total_price":512000,"steps":{"design":true,"materials":true,"fabrication":true,"finishing":false,"delivery":false}},{"id":"5b281f02-01a4-4b4c-8a69-16a73d856ad3","ref":"LUX-P009","title":"Clinic waiting area","client_id":"899bec93-16b6-41a2-a9bd-1270ec43c0fc","type":"custom","status":"in_progress","description":"Durable, easy-to-clean seating benches, reception counter and planters for the clinic’s waiting area.","start_date":"2026-10-06","delivery_date":"2026-12-05","completed_date":null,"total_price":74000,"steps":{"design":true,"materials":true,"fabrication":false,"finishing":false,"delivery":false}},{"id":"070fff0b-6a5c-4503-a702-b5fa06a00865","ref":"LUX-P010","title":"Penthouse interior design","client_id":"8363fa40-c6b3-4d31-aed6-0a2dba8cbd18","type":"interior","status":"in_progress","description":"Complete interior design of a 240 m² penthouse: living, dining, two bedrooms and a home office.","start_date":"2026-10-20","delivery_date":"2027-01-14","completed_date":null,"total_price":210000,"steps":{"design":true,"materials":false,"fabrication":false,"finishing":false,"delivery":false}},{"id":"faa6bec9-e7b5-4e14-babc-204bbc126e0e","ref":"LUX-P011","title":"Dining table Dune & chairs","client_id":"7010a980-ba87-482a-96f8-01dc1cea4d50","type":"catalog","status":"started","description":"Catalog order: table Dune 8 seats with six upholstered chairs.","start_date":"2026-11-09","delivery_date":"2026-12-10","completed_date":null,"total_price":28400,"steps":{"design":false,"materials":false,"fabrication":false,"finishing":false,"delivery":false}},{"id":"579c46ff-1ba0-4782-8939-8a86c9f6d197","ref":"LUX-P012","title":"School library shelving","client_id":"7f7382a7-d307-457a-96ea-03d9ab3d14fe","type":"custom","status":"started","description":"Made-to-measure library: modular shelving, reading benches and a librarian desk.","start_date":"2026-11-12","delivery_date":"2026-12-25","completed_date":null,"total_price":57000,"steps":{"design":false,"materials":false,"fabrication":false,"finishing":false,"delivery":false}}]$j$::jsonb) as x(id uuid,ref text,title text,client_id uuid,type text,status text,description text,start_date date,delivery_date date,completed_date date,total_price int,steps jsonb);
